import AppKit

/// Edit ▸ Cut / Copy / Paste / Paste Attributes (⌘X, ⌘C, ⌘V, ⌥⌘V) — the
/// four menu items `EditorViewController.swift` forwards here — and the
/// fifth, Edit ▸ Paste Graphic Properties, whose action is this file's own.
///
/// The clipboard is one pasteboard type and two ops that read it. Copy writes
/// the selection as the `paste` op's payload (the module doc of
/// `core/src/edit_paste.rs` is its schema) under `com.kgalligan.framejob.clips`;
/// Paste hands that payload straight back to the core, which does all the
/// deciding — fresh ids, media matched by path, the overlap rule, the frame
/// grid — and Paste Attributes and Paste Graphic Properties hand the SAME
/// payload to `paste_attributes`, which reads only its earliest clip's
/// property groups. Nothing about a clip is interpreted on this side.
///
/// **Every reader and writer takes its pasteboard as a parameter**, the
/// general one by default, so a probe can drive Copy and both pastes over a
/// private pasteboard and never touch the owner's clipboard.
///
/// Two decisions worth stating, because neither is forced:
///
/// **The payload is built from the core's own project JSON, not from
/// `ProjectSnapshot`.** The snapshot is a LENIENT read view (its `init(from:)`
/// falls back rather than failing), so re-encoding one would quietly drop
/// whatever this build does not know about and round every field through
/// Swift's idea of the schema. Copying the raw JSON objects means a pasted
/// clip is the clip that was copied, down to the keys nobody has written yet.
///
/// **A payload clip's `track` is rewritten to a DEPTH from the front of the
/// stack** (0 = front-most), because a track id means nothing in another
/// document — and pasting between documents is the case the private
/// pasteboard type exists for. Depth is the only thing about the source's
/// track stack worth carrying: it is what makes a two-lane selection paste
/// back onto two lanes.
extension EditorViewController {
    /// The private pasteboard type the payload travels under. Private on
    /// purpose: a Frame Job clip is not a flavour of anything else, and a paste
    /// from another app is a beep, not a guess.
    static let clipsPasteboardType = NSPasteboard.PasteboardType("com.kgalligan.framejob.clips")

    // MARK: - Copy

    /// ⌘C. Writes the selection to the pasteboard (the general one, unless a
    /// probe names its own), with a short human summary as the plain-text
    /// fallback — pasting into a text editor should say what was copied, not
    /// spill a project.
    ///
    /// Returns whether anything was written, so Cut can stop before it deletes
    /// something it failed to copy.
    @discardableResult
    func copySelection(to pasteboard: NSPasteboard = .general) -> Bool {
        guard let document = document, !document.selection.isEmpty,
              let payload = clipboardPayload(for: document),
              JSONSerialization.isValidJSONObject(payload),
              let data = try? JSONSerialization.data(
                withJSONObject: payload, options: [.sortedKeys])
        else {
            NSSound.beep()
            return false
        }
        // `declareTypes` clears the pasteboard and takes ownership in one
        // call, which is the documented pairing for `setData(_:forType:)`.
        pasteboard.declareTypes([Self.clipsPasteboardType, .string], owner: nil)
        pasteboard.setData(data, forType: Self.clipsPasteboardType)
        pasteboard.setString(clipboardSummary(for: document), forType: .string)
        return true
    }

    /// The `paste` payload for the current selection: the selected clips
    /// verbatim out of `project.json` with each clip's `track` rewritten to
    /// its depth from the front, plus the media rows those clips name.
    ///
    /// nil when the project JSON cannot be read or the selection resolved to
    /// no clips at all — both of which mean there is nothing to put on the
    /// pasteboard, and the caller beeps.
    private func clipboardPayload(for document: ProjectDocument) -> [String: Any]? {
        // The EDITED project (road map 2's phase 9). Inside a nest the
        // selected clips are the NEST's, and they are the top level of this
        // JSON — so a Copy in a nest copies what was picked, and the `track`
        // depths it rewrites are counted against the nest's own stack, which
        // is what the paste on the other side will be measured against.
        guard let data = document.editedProject.json.data(using: .utf8),
              let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let clips = root["clips"] as? [[String: Any]]
        else { return nil }
        let snapshot = document.editedProject.snapshot
        let front = snapshot.tracks.count - 1
        // A selected PICTURE half brings its linked sound, so a pasted
        // detached clip lands as a pair; a selected sound half is copied
        // alone, and the core clears its link on paste (spec §11 AU-96).
        var selection = document.selection
        for id in document.selection {
            if let clip = snapshot.clip(id), clip.enabled.video, let partner = clip.linked {
                selection.insert(partner)
            }
        }

        var payloadClips: [[String: Any]] = []
        var wanted: Set<UInt32> = []
        for clip in clips {
            guard let id = (clip["id"] as? NSNumber)?.uint32Value, selection.contains(id),
                  let track = (clip["track"] as? NSNumber)?.uint32Value,
                  let index = snapshot.trackIndex(of: track)
            else { continue }
            var copied = clip
            copied["track"] = front - index
            payloadClips.append(copied)
            wanted.formUnion(Self.payloadMediaIDs(clip))
        }
        guard !payloadClips.isEmpty else { return nil }
        // A wanted row's Camera Log LUT travels with it (spec §11 GR-16), so
        // the paste lands the conversion remapped rather than dropping it.
        for id in wanted {
            if let lut = snapshot.media(id)?.color?.lut { wanted.insert(lut) }
        }

        // Only the rows the copied clips SHOW or look through, and the LUTs
        // those convert with: a media entry nothing points at would arrive in
        // the other document as a Media-tab row the user cannot account for.
        let media = (root["media"] as? [[String: Any]] ?? []).filter { entry in
            guard let id = (entry["id"] as? NSNumber)?.uint32Value else { return false }
            return wanted.contains(id)
        }
        return ["clips": payloadClips, "media": media]
    }

    /// The media ids one copied clip (its `project.json` object) names: its
    /// source's, its base look's, its gate's (`video.hide_silent.media`, spec
    /// §11 CO-92) and each action end's look's (spec §11 GR-8), in that order
    /// without repeats — the rows a paste into another project needs. An end
    /// may name a LUT that is gone; its row is simply not found.
    static func payloadMediaIDs(_ clip: [String: Any]) -> [UInt32] {
        func lookMedia(_ video: Any?) -> UInt32? {
            guard let video = video as? [String: Any], let look = video["look"] as? [String: Any]
            else { return nil }
            return (look["media"] as? NSNumber)?.uint32Value
        }
        var found: [UInt32?] = [
            ((clip["source"] as? [String: Any])?["media"] as? NSNumber)?.uint32Value,
            lookMedia(clip["video"]),
            (((clip["video"] as? [String: Any])?["hide_silent"] as? [String: Any])?["media"]
                as? NSNumber)?.uint32Value,
        ]
        for action in clip["actions"] as? [[String: Any]] ?? [] {
            found.append(lookMedia((action["end"] as? [String: Any])?["video"]))
        }
        var ids: [UInt32] = []
        for id in found.compactMap({ $0 }) where !ids.contains(id) { ids.append(id) }
        return ids
    }

    /// The plain-text fallback: what was copied and the span it covered, in
    /// the document's own timecode (`ReelTime.format`, as everywhere else).
    private func clipboardSummary(for document: ProjectDocument) -> String {
        let clips = selectedClips
        let canvas = document.editedProject.snapshot.canvas
        let frames = canvas.timecodeFrames
        let start = clips.first?.start ?? 0
        let end = clips.map { $0.end }.max() ?? start
        let count = clips.count == 1 ? "1 clip" : "\(clips.count) clips"
        return "Frame Job — \(count), "
            + ReelTime.format(start, fps: canvas.fps, frames: frames) + " to "
            + ReelTime.format(end, fps: canvas.fps, frames: frames)
    }

    // MARK: - Cut

    /// ⌘X. Copy, then exactly the edit ⌫ performs — ONE undo step, because
    /// the copy touches no model state and the delete is a single op.
    func cutSelection() {
        guard let document = document, !document.selection.isEmpty else {
            NSSound.beep()
            return
        }
        guard copySelection() else { return }
        document.applyEdit("Cut", .delete(clips: Array(document.selection)))
    }

    // MARK: - Paste

    /// ⌘V. The payload lands at the playhead and whatever appeared is
    /// selected, so the paste can be dragged or styled straight away.
    ///
    /// Placement is entirely the core's: `paste` puts a clip the overlap rule
    /// refuses on a new track in front rather than refusing the edit, so the
    /// only beeps here are an empty pasteboard and a payload the core reports
    /// as invalid (through `applyEdit`, which presents the message).
    func pasteClips() {
        guard let document = document, let payload = pasteboardPayload() else {
            NSSound.beep()
            return
        }
        let before = document.editedProject.snapshot
        document.applyEdit("Paste", .paste(at: document.playhead, payload: payload))
        selectClips(addedSince: before, in: document)
    }

    // MARK: - Paste Attributes

    /// ⌥⌘V. The payload's EARLIEST clip's LOOK — its video, audio, text and
    /// shape groups, the earliest by start, then the front-most track, then
    /// the lower id — onto every selected clip, leaving `groups` to the core's
    /// default (every group both sides have, spec §6). Nothing that makes the
    /// clip THIS clip travels: not its place, speed, actions, transition, name
    /// or label, and not a text clip's words or a shape's geometry.
    ///
    /// Whole selection, one op, one undo step. An IDENTITY — the payload's
    /// clip and the targets share no group, or the look is already theirs —
    /// is `applyEdit`'s beep, and an out-of-range payload is its error,
    /// presented. There is no group picker here: the default rule is what
    /// ⌥⌘V has always meant in a cutting room, and the agent's tool
    /// (`paste_attributes`) takes `groups` for anyone who needs the choice.
    func pasteAttributes(from pasteboard: NSPasteboard = .general) {
        guard let document = document, !document.selection.isEmpty,
              let payload = pasteboardPayload(on: pasteboard)
        else {
            NSSound.beep()
            return
        }
        document.applyEdit(
            "Paste Attributes",
            .pasteAttributes(clips: Array(document.selection), payload: payload))
    }

    // MARK: - Paste Graphic Properties

    /// Edit ▸ Paste Graphic Properties (spec §11 G-32), which has no key. A
    /// menu sends its `NSMenuItem`, so the app reads the general pasteboard;
    /// a probe sends this action a private pasteboard as its sender, which
    /// is how the line below is measured and not only typechecked.
    @objc func pasteGraphicProperties(_ sender: Any?) {
        pasteGraphicProps(from: sender as? NSPasteboard ?? .general)
    }

    /// The copied graphic's props — all of them, its words included — onto
    /// every selected clip drawn by the SAME graphic; each keeps its own
    /// size, in point and length. ONE op, and nothing about the payload is
    /// read here: `groups: ["graphic"]` names the group ⌥⌘V never carries,
    /// and `skipMissing` makes the core skip a selected clip that cannot take
    /// it rather than refuse the paste. So when the copied clip is not a
    /// graphic, or no selected clip is drawn by the same one, the answer is
    /// an identity — `applyEdit`'s beep — and copied props the core will not
    /// store, onto a clip that takes them, are its sentence in an alert.
    func pasteGraphicProps(from pasteboard: NSPasteboard = .general) {
        guard let document = document, !document.selection.isEmpty,
              let payload = pasteboardPayload(on: pasteboard)
        else {
            NSSound.beep()
            return
        }
        document.applyEdit(
            "Paste Graphic Properties",
            .pasteAttributes(
                clips: Array(document.selection), payload: payload,
                groups: ["graphic"], skipMissing: true))
    }

    /// The payload on the pasteboard, or nil when there is nothing of ours
    /// there to paste — an empty pasteboard, another app's content, or a
    /// payload with no clips in it.
    private func pasteboardPayload(on pasteboard: NSPasteboard = .general) -> [String: Any]? {
        guard let data = pasteboard.data(forType: Self.clipsPasteboardType),
              let payload = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let clips = payload["clips"] as? [Any], !clips.isEmpty
        else { return nil }
        return payload
    }

    /// Whether ⌘V has anything to do. Only the TYPE is inspected, not the
    /// bytes: this runs on every menu validation, and reading a pasteboard's
    /// available types is cheap where decoding its data is not.
    func canPasteClips(on pasteboard: NSPasteboard = .general) -> Bool {
        pasteboard.availableType(from: [Self.clipsPasteboardType]) != nil
    }

    // MARK: - Validation

    /// The half of `validateUserInterfaceItem` this file owns. nil means "not
    /// mine" and leaves the base file's answer alone.
    func validateClipboardAction(
        _ action: Selector, pasteboard: NSPasteboard = .general
    ) -> Bool? {
        guard let document = document else { return false }
        switch action {
        case #selector(cut(_:)), #selector(copy(_:)):
            return !document.selection.isEmpty
        case #selector(paste(_:)):
            return canPasteClips(on: pasteboard)
        case #selector(pasteAttributes(_:)):
            // Paste needs no selection (the clips land at the playhead);
            // Paste Attributes needs something to paste ONTO.
            return canPasteClips(on: pasteboard) && !document.selection.isEmpty
        case #selector(pasteGraphicProperties(_:)):
            // Something of ours to read and a graphic to paste onto. WHAT was
            // copied is not read here (the bytes, on every menu validation):
            // a copied clip that is not a graphic is the item's beep (G-32).
            return canPasteClips(on: pasteboard)
                && selectedClips.contains { $0.source == .graphic && $0.graphic != nil }
        default:
            return nil
        }
    }
}
//! `paste` — the clipboard's half of Cut / Copy / Paste (spec §6, table
//! "Clips").
//!
//! Its own module because pasting is a different concern from every other
//! placement op: the material does not come from the project. A `move_clip`
//! or a `duplicate` rearranges clips the project already owns, so the ids,
//! the media and the tracks all exist; a paste arrives as JSON that may have
//! been written by ANOTHER document — a different id space, a different
//! media list, a different frame grid, possibly a different canvas — and has
//! to be made to fit before a single clip lands.
//!
//! ### The payload
//!
//! ```json
//! {"clips": [ …the §5.2 clip objects… ], "media": [ …the §5.2 media rows… ],
//!  "nests": [ …the §5.2 nest objects the clips show… ]}
//! ```
//!
//! It is exactly what `EditorViewController+Clipboard.swift` puts on
//! `NSPasteboard.general` under `com.kgalligan.framejob.clips`: the clips
//! copied verbatim out of the source document's own `project.json`, plus the
//! media rows those clips name and any nest they show. Four things about it
//! are worth stating before the code:
//!
//! 1. **A payload clip's `track` is a DEPTH, not an id** — 0 is the
//!    front-most track the copy covered, 1 the one behind it, and so on. A
//!    track id from another document means nothing here, and the depth is
//!    the only thing about the source's track stack worth carrying: it is
//!    what makes a two-lane selection paste back onto two lanes.
//! 2. **Ids are re-minted, always.** Clips, actions, any media row the
//!    project does not already have, and every nest — with its tracks, its
//!    clips and their actions — get fresh ids from `next_id`, so a payload
//!    can be pasted repeatedly and into the document it came from.
//! 3. **A nest is COPIED, never matched.** Media is matched by path because
//!    it names a file two documents can share; a nest is content, and two
//!    nests that look alike are no more the same object than two clips are.
//!    So every paste of a nest clip brings its own copy, and editing one
//!    afterwards leaves the other alone.
//! 4. **Unknown keys are ignored**, deliberately: no `deny_unknown_fields`
//!    here. The payload is machine-written, a future build will add keys to
//!    it, and refusing a whole paste over a key this build has not learned
//!    yet would be worse than dropping it — the same reasoning `model.rs`
//!    gives for the project schema itself.
//!
//! ### Making it fit
//!
//! Every project time is re-snapped to THIS document's frame grid
//! ([`Project::snapped`]), because the payload may come from a document at
//! another rate; source times are not, for the same reason `trim_start` and
//! `split` do not snap them — an `in` point is measured on the media's grid,
//! not the canvas's. Media is matched to the existing `media[]` **by path**,
//! which is `add_media`'s one-entry-per-path rule, so pasting between two
//! documents that both reference `/m/talk.mov` reuses the row that is there
//! and pasting into a document that has never seen it brings the row along;
//! a row brought along first passes `add_media`'s field checks, with its
//! `original` stored as `add_media` stores it, and a row matched by path is
//! the project's own and is not checked. Every group of every clip that
//! lands, nested ones included, first passes the patch path's
//! normalise-and-check, as `paste_attributes`' do — a video group
//! `set_video`'s own chain, `Project::settle_video`.
//!
//! Placement obeys the overlap rule like everything else (spec §11), and a
//! clip the rule refuses on its target track goes on a NEW track in front —
//! the same fallback `EditorViewController+AddClips.swift` uses for Add
//! Text, and for the same reason: a paste at a busy playhead should land
//! somewhere visible rather than beep. That fallback is why the only
//! "changes nothing" answer here is an empty clip list.
//!
//! `paste_attributes` reads the same payload and places nothing; it is
//! `edit_paste_attributes.rs`'s, which parses the payload through
//! [`parse_payload`].

use std::collections::HashMap;

use serde::Deserialize;
use serde_json::Value;

use crate::edit_commit::Landing;
use crate::edit_link::relink_copies;
use crate::edit_track::{check_media_fields, normalize_original};
use crate::export::describe;
use crate::format::MAX_TRACKS;
use crate::lut::{look_media_ids, remap_look_media};
use crate::model::{Clip, Media, Nest, Project, Source};
use crate::outcome::Outcome;
use crate::time::Ticks;
use crate::video_gate::{hide_silent_media, remap_hide_silent};

/// One clipboard payload. `media` and `nests` default because most
/// selections name neither; `clips` deliberately does not, so a payload that
/// forgot the key is an error naming it rather than a silent no-op.
#[derive(Debug, Deserialize)]
pub(crate) struct Payload {
    pub(crate) clips: Vec<Clip>,
    #[serde(default)]
    pub(crate) media: Vec<Media>,
    #[serde(default)]
    pub(crate) nests: Vec<Nest>,
}

/// The nest a source shows, or `None` for every other kind.
fn source_nest(source: &Source) -> Option<u32> {
    match source {
        Source::Nest { project } => Some(*project),
        _ => None,
    }
}

/// The same source pointing at this project's media and nest ids.
///
/// An id neither map carries is impossible — [`absorb_media`] and
/// [`absorb_nests`] resolve every one the clips name before this runs — but
/// ids are passed through rather than unwrapped, so a future caller that
/// skipped a step gets `validate`'s "refers to unknown media" or "refers to
/// unknown nest" instead of a panic.
fn remap_source(source: &Source, media: &HashMap<u32, u32>, nests: &HashMap<u32, u32>) -> Source {
    let mapped = |id: &u32| media.get(id).copied().unwrap_or(*id);
    match source {
        Source::Media {
            media: id,
            r#in,
            reversed,
        } => Source::Media {
            media: mapped(id),
            r#in: (*r#in).max(0),
            reversed: *reversed,
        },
        Source::Still { media: id, at } => Source::Still {
            media: mapped(id),
            at: (*at).max(0),
        },
        Source::Image { media: id } => Source::Image { media: mapped(id) },
        Source::Nest { project } => Source::Nest {
            project: nests.get(project).copied().unwrap_or(*project),
        },
        other => other.clone(),
    }
}

/// The payload nests the pasted clips show, directly or through one
/// another, in the order they are discovered.
///
/// The traversal is the same shape `validate`'s cycle check uses: an id is
/// queued once, so a payload whose nests point at each other terminates here
/// and is refused later by `validate`, where the message about a cycle
/// already lives.
///
/// `Err` when a clip shows a nest the payload does not carry — a truncated
/// or hand-written payload, whose clip would otherwise become a dangling
/// reference.
fn reachable_nests(payload: &Payload) -> Result<Vec<&Nest>, String> {
    let mut wanted: Vec<u32> = Vec::new();
    for clip in &payload.clips {
        if let Some(id) = source_nest(&clip.source) {
            if !wanted.contains(&id) {
                wanted.push(id);
            }
        }
    }
    let mut found: Vec<&Nest> = Vec::new();
    let mut index = 0;
    while let Some(id) = wanted.get(index).copied() {
        index += 1;
        let Some(nest) = payload.nests.iter().find(|n| n.id == id) else {
            return Err(format!(
                "a pasted clip shows nest {id}, which the payload does not carry"
            ));
        };
        found.push(nest);
        for child in nest.child_nests() {
            if !wanted.contains(&child) {
                wanted.push(child);
            }
        }
    }
    Ok(found)
}

/// Copies every reachable payload nest into the project with fresh ids
/// throughout — the nest, its tracks, its clips and their actions — and
/// returns the payload-id → project-id map.
///
/// Every nest gets its new id BEFORE any is rewritten, so a nest showing
/// another nest is remapped whichever order the two were discovered in.
/// Times inside are re-snapped to this document's frame grid for the same
/// reason the pasted clips' are: the payload may come from a document at
/// another rate, and nothing sub-frame may reach the model.
///
/// `Err` when a clip inside fails [`Project::normalise_and_check_pasted`].
/// That runs in a second pass, once every copy is in, so a clip showing a
/// nest is measured against the copy it shows.
fn absorb_nests(
    project: &mut Project,
    nests: &[&Nest],
    media: &HashMap<u32, u32>,
) -> Result<HashMap<u32, u32>, String> {
    let mut map: HashMap<u32, u32> = HashMap::new();
    for nest in nests {
        map.insert(nest.id, project.allocate_id());
    }
    let first = project.nests.len();
    for nest in nests {
        let mut copy = (*nest).clone();
        copy.id = map.get(&nest.id).copied().unwrap_or(nest.id);
        let mut tracks: HashMap<u32, u32> = HashMap::new();
        for track in copy.tracks.iter_mut() {
            let id = project.allocate_id();
            tracks.insert(track.id, id);
            track.id = id;
        }
        let mut fresh: HashMap<u32, u32> = HashMap::new();
        for clip in copy.clips.iter_mut() {
            let old = clip.id;
            project.remint(clip);
            fresh.insert(old, clip.id);
            clip.track = tracks.get(&clip.track).copied().unwrap_or(clip.track);
            clip.source = remap_source(&clip.source, media, &map);
            remap_look_media(clip, media);
            remap_hide_silent(clip, media);
            // The speed BEFORE the duration: the bound is measured at it.
            if !(clip.speed.is_finite() && clip.speed > 0.0) {
                clip.speed = 1.0;
            }
        }
        // A copied pair re-pairs through the fresh ids (spec §11 AU-96).
        relink_copies(&mut copy.clips, &fresh);
        project.nests.push(copy);
    }
    for (offset, nest) in nests.iter().enumerate() {
        let index = first + offset;
        let Some(mut clips) = project.nests.get(index).map(|n| n.clips.clone()) else {
            continue;
        };
        for (clip, source) in clips.iter_mut().zip(&nest.clips) {
            project.normalise_and_check_pasted(clip, source.id)?;
            project.resnap_clip_times(clip);
        }
        if let Some(copy) = project.nests.get_mut(index) {
            copy.clips = clips;
        }
    }
    Ok(map)
}

